import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Constants
API_SPEC_PATH = 'api.json'
ENDPOINT = '/user/login'
METHOD = 'get'
TEST_DATA_FILENAME = 'user_login.json'

# Load Endpoint Test Data
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / TEST_DATA_FILENAME

def _load_json_file(file_path):
    with open(file_path, 'r') as f:
        return json.load(f)

_ENDPOINT_DATA = _load_json_file(_endpoint_data_path)
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [f"{case['scenario']}-{case['username']}" for case in _ENDPOINT_DATA]

# Validator Instance
validator = SwaggerSchemaValidator(API_SPEC_PATH)

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
@pytest.mark.smoke
def test_user_login(api_client, config_test_data, scenario_case):
    """
    Test the user login endpoint for various scenarios.
    """
    # Merge test data
    test_data = {**config_test_data, **scenario_case}

    # Prepare request
    params = {
        "username": test_data.get("username"),
        "password": test_data.get("password")
    }

    # Validate request schema
    request_validation = validator.validate_json(params, "LoginRequestSchema")
    assert request_validation['valid'], f"Request validation failed: {request_validation['message']}"

    # Execute request
    response = api_client.get(ENDPOINT, params=params)

    # Validate response schema
    response_validation = validator.validate_schema_by_response(
        endpoint=ENDPOINT,
        method=METHOD,
        status_code=str(response.status_code),
        response=response
    )
    assert response_validation['valid'], f"Response validation failed: {response_validation['message']}"

    # Assert expected status code
    assert response.status_code == test_data["statusCode"], f"Expected {test_data['statusCode']}, got {response.status_code}"

@pytest.mark.parametrize("invalid_auth", ["InvalidToken", None])
def test_user_login_auth_failure(api_client, invalid_auth):
    """
    Test the user login endpoint with invalid authentication.
    """
    params = {
        "username": "invalid_user",
        "password": "invalid_pass"
    }

    headers = {
        "Authorization": f"Bearer {invalid_auth}" if invalid_auth else ""
    }

    # Execute request
    response = api_client.get(ENDPOINT, params=params, headers=headers)

    # Validate response schema for error
    response_validation = validator.validate_schema_by_response(
        endpoint=ENDPOINT,
        method=METHOD,
        status_code=str(response.status_code),
        response=response
    )
    assert response_validation['valid'], f"Response validation failed: {response_validation['message']}"

    # Assert expected status code for unauthorized
    assert response.status_code != 200, f"Unexpected success with invalid auth: {response.status_code}"
